import {bindRoom,boundPlayback} from './room-fixture.mjs';
import test from 'node:test';
import assert from 'node:assert/strict';
import {LiveMediaView} from '../../podvoice/gatekeeper/static/podview/live-media-view.js';
import {LiveQueueView} from '../../podvoice/gatekeeper/static/podview/live-queue-view.js';
import {PlayerView} from '../../podvoice/gatekeeper/static/podview/player-view.js';
import {NotificationQueue} from '../../podvoice/gatekeeper/static/podview/ui/notification-queue.js';
const deferred=()=>{let resolve;const promise=new Promise(done=>resolve=done);return {promise,resolve};};
const account=(id,title)=>({config_entry_id:id,title});
const rawPayload=id=>({ok:true,data:{ok:true,schema:'podconnect.playback.v1',config_entry_id:id,owner_epoch:'epoch',poll_sequence:1,physical_result_verified:false,observation:{status:'fresh',source:'spotify_web_api',age_ms:0,max_age_ms:15000,observed_at:new Date().toISOString()},playback:{state:'playing',target:{kind:'spotify_device',target_id:'device',name:'Actual speaker'},item:{type:'track',uri:'spotify:track:0123456789ABCDEFGHIJKL',name:'Actual song',artists:['Artist'],duration_ms:1}}}});
const payload=id=>{const snapshot={bootId:'boot',roomId:'r0'},binding=bindRoom(snapshot,id);return {ok:true,schema:'podview.room-playback.v1',bootId:'boot',roomId:'r0',configEntryId:id,binding,status:'observed',data:{...rawPayload(id).data,room_proof_valid_until:Date.now()/1000+10}};};
function surface(){const previous=globalThis.document,queue={replaceChildren(){}},button=()=>({dataset:{},setAttribute(){},addEventListener(){}});globalThis.document={getElementById:id=>queue,createElement:button};const changes=[],calls=[],host={isConnected:true,liveSnapshot:{bootId:'boot',roomId:'r0',capabilities:{musicRead:['targets','playback','queue']}},liveTransport:{connected:true,music:async(kind,id)=>{calls.push([kind,id]);return kind==='targets'?{ok:true,data:{accounts:[account('first','Konto et')]}}:payload(id);}},liveMusicAccountChanged:id=>changes.push(id)};bindRoom(host.liveSnapshot,'first');const view=Object.create(LiveMediaView.prototype);Object.assign(view,{host,generation:0,account:null,lastRead:0,pending:false,queuePending:false,rows:new Map(),accounts:{children:[],replaceChildren(){this.children=[];},append(b){this.children.push(b);}},queueNote:{textContent:''},render(){},renderQueue(){}});view.queueControls=new LiveQueueView(host);host.liveMedia=view;return {view,host,changes,calls,restore:()=>globalThis.document=previous};}
class DOMNode extends EventTarget{
 constructor(tag='div'){super();this.tagName=tag.toUpperCase();this.children=[];this.dataset={};this.style={getPropertyValue(key){return this[key]||'';},setProperty(key,value){this[key]=value;}};this.attributes=new Map();this.hidden=false;this.disabled=false;this.textContent='';this.className='';this.classList={add:x=>{this.className=[...new Set([...this.className.split(' ').filter(Boolean),x])].join(' ');},remove:x=>{this.className=this.className.split(' ').filter(c=>c!==x).join(' ');},contains:x=>this.className.split(' ').includes(x)};}
 append(...nodes){for(const n of nodes){n.remove();n.parentNode=this;this.children.push(n);}}
 insertBefore(n,before){n.remove();n.parentNode=this;const index=this.children.indexOf(before);if(index<0)this.children.push(n);else this.children.splice(index,0,n);}
 remove(){if(this.parentNode){const a=this.parentNode.children;a.splice(a.indexOf(this),1);this.parentNode=null;}}
 replaceChildren(...nodes){for(const n of [...this.children])n.remove();this.append(...nodes);}
 setAttribute(k,v){this.attributes.set(k,String(v));}getAttribute(k){return k==='src'?(this.src??null):(this.attributes.get(k)??null);}removeAttribute(k){this.attributes.delete(k);}
 querySelector(tag){return this.children.find(n=>n.tagName===tag.toUpperCase())||null;}
 close(){this.open=false;}click(){if(!this.disabled)this.dispatchEvent(new Event('click'));}
}
function domSurface(){const f=surface(),nodes=new Map(),groups=new Map(),doc={getElementById:id=>{if(!nodes.has(id))nodes.set(id,new DOMNode());return nodes.get(id);},createElement:tag=>new DOMNode(tag),querySelector:selector=>groups.get(selector)};globalThis.document=doc;f.host.ownerDocument=doc;f.host.dataset={};f.host.querySelector=selector=>{if(!groups.has(selector))groups.set(selector,new DOMNode());return groups.get(selector);};doc.getElementById('detail-output').append(new DOMNode('span'));doc.getElementById('player-empty').append(new DOMNode('p'));const selected=[];f.host.playerView=new PlayerView(f.host,{chooseQueue:item=>selected.push(item)});f.view.render=LiveMediaView.prototype.render;f.view.renderQueue=LiveMediaView.prototype.renderQueue;return {...f,doc,nodes,groups,selected};}
test('single real account auto-select notifies catalogue and binds playback request',async()=>{const f=surface();try{await f.view.refresh();assert.equal(f.view.account,'first');assert.deepEqual(f.changes,['first']);assert.deepEqual(f.calls,[['targets',undefined],['playback','first']]);assert.equal(f.view.playback.item.name,'Actual song');}finally{f.restore();}});
test('manual account switch revokes old playback/catalogue immediately and rejects unknown accounts',async()=>{const f=surface();try{f.view.accounts.data={items:[{id:'first',label:'First'},{id:'second',label:'Second'}]};f.view.account='first';f.view.playback={owner_epoch:'old'};const hold=deferred();f.host.liveTransport.music=()=>hold.promise;bindRoom(f.host.liveSnapshot,'second');f.view.selectAccount('second');assert.equal(f.view.account,'second');assert.equal(f.view.playback,null);assert.deepEqual(f.changes,[null,'second']);f.view.selectAccount('unknown');assert.equal(f.view.account,'second');hold.resolve(payload('second'));await new Promise(done=>setImmediate(done));assert.equal(f.view.playback.config_entry_id,'second');}finally{f.restore();}});
test('late playback after account, boot, room or capability replacement never updates',async()=>{for(const change of [f=>f.view.account='second',f=>f.host.liveSnapshot.bootId='new',f=>f.host.liveSnapshot.roomId='other',f=>f.host.liveSnapshot.capabilities.musicRead=['playback']]){const f=surface();try{f.view.account='first';const hold=deferred();f.host.liveTransport.music=()=>hold.promise;const reading=f.view.refresh();change(f);hold.resolve(payload('first'));await reading;assert.equal(f.view.playback,undefined);}finally{f.restore();}}});
test('owner epoch replacement clears queue and notifies same-account catalogue revocation',async()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'old',poll_sequence:2,expiresAt:Date.now()+10000},'first');f.view.queue={items:[]};await f.view.refresh();assert.equal(f.view.playback.owner_epoch,'epoch');assert.equal(f.view.queue,null);assert.deepEqual(f.changes,['first']);}finally{f.restore();}});
test('late queue after boot or read-capability replacement never establishes a new list',async()=>{for(const change of [f=>f.host.liveSnapshot.bootId='new',f=>f.host.liveSnapshot.capabilities.musicRead=['queue']]){const f=surface();try{f.view.account='first';const hold=deferred();f.host.liveTransport.music=()=>hold.promise;const reading=f.view.loadQueue();change(f);hold.resolve({ok:true,data:{ok:true,schema:'podconnect.queue.v1',config_entry_id:'first',owner_epoch:'epoch',snapshot_id:'epoch:q:1',scope:'account',relation_to_playback:'not_atomic',observed_at:new Date().toISOString(),returned_count:0,items:[]}});await reading;assert.equal(f.view.queue,undefined);}finally{f.restore();}}});
test('initial playback read failure exposes error state without inventing playback and leaves no pending read',async()=>{const f=surface();try{f.view.account='first';f.host.liveTransport.music=async()=>{throw Error('unavailable');};await f.view.refresh();assert.equal(f.view.readState,'error');assert.equal(f.view.playback,null);assert.equal(f.view.pending,false);}finally{f.restore();}});
test('disconnect retains same-room playback and queue as read-only stale display',()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');const key=JSON.stringify(['boot','r0','first',f.view.playback.roomBinding.bindingId,'epoch','device',null,null,null,null,null]);f.view.queueControls.retained={key,items:[{id:'occurrence',title:'Queued song',artist:'Artist',order:1}]};const shown={};f.host.playerView={renderPlayer:vm=>shown.player=vm,renderQueue:(items,meta)=>shown.queue={items,meta},renderControls(){}};f.view.render=LiveMediaView.prototype.render;f.view.renderQueue=LiveMediaView.prototype.renderQueue;f.host.liveTransport.connected=false;f.view.invalidate();assert.equal(shown.player.title,'Actual song');assert.equal(shown.player.active,true);assert.equal(shown.player.fresh,false);assert.equal(shown.player.canOutput,false);assert.equal(shown.queue.items[0].title,'Queued song');assert.equal(shown.queue.items[0].selectable,false);assert.equal(shown.queue.meta.status,'stale');assert.equal(f.view.queueControls.offer,null);}finally{f.restore();}});
test('transient same-owner playback read error retains only stale display and revokes queue offer',async()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');const key=JSON.stringify(['boot','r0','first',f.view.playback.roomBinding.bindingId,'epoch','device',null,null,null,null,null]);f.view.queueControls.retained={key,items:[{id:'occurrence',title:'Queued song',artist:'Artist',order:1}]};f.view.queueControls.offer={};f.host.liveTransport.music=async()=>{throw new TypeError('Failed to fetch');};const shown={};f.host.playerView={renderPlayer:vm=>shown.player=vm,renderQueue:(items,meta)=>shown.queue={items,meta},renderControls(){}};f.view.render=LiveMediaView.prototype.render;f.view.renderQueue=LiveMediaView.prototype.renderQueue;await f.view.refresh();assert.equal(f.view.readState,'error');assert.equal(shown.player.title,'Actual song');assert.equal(shown.player.fresh,false);assert.equal(shown.queue.items[0].title,'Queued song');assert.equal(shown.queue.items[0].selectable,false);assert.equal(f.view.queueControls.offer,null);}finally{f.restore();}});
test('opening detail offline keeps a bound queue visible and makes no source read',async()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');const key=JSON.stringify(['boot','r0','first',f.view.playback.roomBinding.bindingId,'epoch','device',null,null,null,null,null]);f.view.queueControls.retained={key,items:[{id:'occurrence',title:'Queued song',artist:'Artist',order:1}]};const shown={};f.host.playerView={renderQueue:(items,meta)=>shown.queue={items,meta}};f.view.renderQueue=LiveMediaView.prototype.renderQueue;f.host.liveTransport.connected=false;f.view.invalidate();await f.view.loadQueue();assert.equal(shown.queue.items[0].title,'Queued song');assert.equal(shown.queue.items[0].selectable,false);assert.equal(f.view.queueControls.retained.items.length,1);assert.deepEqual(f.calls,[]);}finally{f.restore();}});
test('revoking queue read capability removes retained rows without a scope change',()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');f.view.queueControls.retained={key:'old',items:[{id:'occurrence'}]};const shown={};f.host.playerView={renderQueue:(items,meta)=>shown.queue={items,meta}};f.view.renderQueue=LiveMediaView.prototype.renderQueue;f.host.liveSnapshot.capabilities.musicRead=['targets','playback'];f.view.renderQueue();assert.deepEqual(shown.queue.items,[]);assert.equal(f.view.queueControls.retained,null);}finally{f.restore();}});
test('expired same-room playback keeps its geometry while a new read is pending',async()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()-1,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');const hold=deferred();f.host.liveTransport.music=()=>hold.promise;const shown={};f.host.playerView={renderPlayer:vm=>shown.player=vm,renderControls(){},renderQueue(){}};f.view.render=LiveMediaView.prototype.render;f.view.renderQueue=LiveMediaView.prototype.renderQueue;const reading=f.view.refresh();assert.equal(shown.player.title,'Actual song');assert.equal(shown.player.active,true);assert.equal(shown.player.loading,false);assert.equal(shown.player.fresh,false);assert.equal(shown.player.canOutput,true);hold.resolve(payload('first'));await reading;assert.equal(f.view.playback.item.name,'Actual song');}finally{f.restore();}});
test('same-bound expiry before refresh keeps the real player and queue visible without action authority',async()=>{
 const f=domSurface();
 try{
  f.view.account='first';f.view.readState='ready';f.host.liveSnapshot.capabilities.queueSelection=true;
  f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist'],uri:'spotify:track:0123456789ABCDEFGHIJKL'},target:{name:'Actual speaker'}},'first');
  const key=JSON.stringify(['boot','r0','first',f.view.playback.roomBinding.bindingId,'epoch','device',null,null,null,null,null]);
  f.view.queueControls.retained={key,items:[{id:'occurrence',title:'Queued song',artist:'Artist',order:1,uri:'spotify:track:0123456789ABCDEFGHIJKL',artwork:null}]};
  f.view.queueControls.offer={expiresAt:Date.now()+10000,pollSequence:1};f.view.queueControls.status='ready';
  f.view.render();
  const queue=f.nodes.get('queue'),row=queue.children[0],cover=f.nodes.get('cover'),coverSrc=cover.src;
  assert.equal(row.disabled,false);queue.scrollTop=72;f.doc.getElementById('music-detail').hidden=false;
  f.view.playback.expiresAt=Date.now()-1;
  f.host.liveSnapshot={...f.host.liveSnapshot,revision:2};
  f.view.render(); // widget-view renders the accepted snapshot before calling refresh().
  assert.equal(f.nodes.get('track-name').textContent,'Actual song');
  assert.equal(f.nodes.get('player-state').textContent,'Sidst kendt');
  assert.equal(f.nodes.get('music-detail').hidden,false);
  assert.equal(f.nodes.get('cover'),cover);assert.equal(cover.src,coverSrc);
  assert.equal(queue.children[0],row);assert.equal(queue.scrollTop,72);
  assert.equal(f.nodes.get('queue-title').textContent,'Sidst kendte kø');
  assert.equal(f.nodes.get('output').disabled,!f.host.liveTransport.connected);assert.equal(f.nodes.get('play-pause').disabled,true);
  assert.equal(f.nodes.get('volume').disabled,true);assert.equal(row.disabled,true);
  assert.equal(f.view.queueControls.offer,null);row.click();assert.deepEqual(f.selected,[]);assert.deepEqual(f.calls,[]);
  const unavailable={...payload('first'),status:'unavailable',data:null};
  f.host.liveTransport.music=async()=>unavailable;f.view.lastRead=0;await f.view.refresh();
  assert.equal(f.view.playback,null);assert.equal(f.nodes.get('track-name').textContent,'');
  assert.equal(f.nodes.get('music-detail').hidden,false,'left detail stays mounted when playback becomes unavailable');assert.equal(f.nodes.get('detail-title').textContent,'Afspiller');assert.equal(f.nodes.get('detail-status').textContent,'Vælg en stemning eller sang.');assert.equal(f.nodes.get('detail-status').textContent,f.host.playerView.emptyCopy.textContent,'unavailable playback uses the same honest state on both player surfaces');assert.equal(f.nodes.get('detail-track').textContent,'');assert.equal(f.view.queueControls.retained,null);
 }finally{f.restore();}
});
test('queue empty slot distinguishes missing access, pending read, error and observed empty queue',async()=>{
 const f=domSurface();
 try{
  f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',target:{name:'Actual speaker'}},'first');
  const queue=f.nodes.get('queue');await f.view.loadQueue();f.view.renderQueue();
  assert.deepEqual(f.calls,[]);assert.equal(queue.dataset.status,'unavailable');
  assert.equal(queue.children.length,1);assert.equal(queue.children[0].className,'queue-empty');
  assert.equal(queue.children[0].textContent,'Køen er ikke tilgængelig med den aktuelle adgang.');
  f.host.liveSnapshot.capabilities.queueSelection=true;
  f.view.queueControls.status='unavailable';f.view.renderQueue();
  assert.equal(queue.children[0].textContent,'Ingen bekræftet kø at vise.');
  f.view.queueControls.status='loading';f.view.queueControls.pending=true;f.view.renderQueue();
  assert.equal(queue.dataset.status,'loading');assert.equal(queue.getAttribute('aria-busy'),'true');
  assert.equal(queue.children.length,3);assert.equal(queue.children.every(row=>row.disabled&&row.dataset.empty==='true'),true);
  f.view.queueControls.pending=false;f.view.queueControls.status='error';f.view.renderQueue();
  assert.equal(queue.dataset.status,'error');assert.equal(queue.children.length,1);
  assert.equal(queue.children[0].textContent,'Køen kunne ikke hentes.');
  f.view.queueControls.status='unknown';f.view.renderQueue();
  assert.equal(queue.dataset.status,'unknown');assert.equal(queue.children[0].textContent,'Køvalg kunne ikke bekræftes.');
  const key=JSON.stringify(['boot','r0','first',f.view.playback.roomBinding.bindingId,'epoch','device',null,null,null,null,null]);
  f.view.queueControls.retained={key,items:[]};f.view.queueControls.offer={expiresAt:Date.now()+10000,pollSequence:1};f.view.queueControls.status='ready';f.view.renderQueue();
  assert.equal(queue.dataset.status,'ready');assert.equal(queue.children.length,1);
  assert.equal(queue.children[0].textContent,'Ingen sange i køen.');
 }finally{f.restore();}
});
test('foreign binding cannot leak the old playback state through control labels',()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');const shown={};f.host.playerView={renderPlayer:vm=>shown.player=vm,renderControls:vm=>shown.controls=vm,renderQueue(){}};f.view.render=LiveMediaView.prototype.render;f.view.renderQueue=LiveMediaView.prototype.renderQueue;f.host.liveSnapshot.roomId='foreign';f.view.render();assert.equal(shown.player.active,false);assert.equal(shown.player.title,'');assert.equal(shown.controls.playing,false);assert.equal(f.view.playback,null);f.host.liveSnapshot.roomId='r0';f.view.render();assert.equal(shown.player.active,false);assert.equal(shown.player.title,'');}finally{f.restore();}});
test('playback-read revocation redacts player and queue before the next refresh',()=>{const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');f.view.queueControls.retained={key:'old',items:[{id:'occurrence'}]};const shown={};f.host.playerView={renderPlayer:vm=>shown.player=vm,renderControls:vm=>shown.controls=vm,renderQueue:(items,meta)=>shown.queue={items,meta}};f.view.render=LiveMediaView.prototype.render;f.view.renderQueue=LiveMediaView.prototype.renderQueue;f.host.liveSnapshot.capabilities.musicRead=['targets','queue'];f.view.render();assert.equal(shown.player.active,false);assert.equal(shown.player.title,'');assert.equal(shown.player.canOutput,true);assert.equal(shown.controls.playing,false);assert.deepEqual(shown.queue.items,[]);assert.equal(f.view.queueControls.retained,null);assert.equal(f.view.playback,null);f.host.liveSnapshot.capabilities.musicRead=['targets','playback','queue'];f.view.render();assert.equal(shown.player.active,false);assert.equal(shown.player.title,'');assert.equal(f.view.playback,null);assert.deepEqual(f.calls,[]);}finally{f.restore();}});
test('explicit server denial clears last-known playback and queue',async()=>{for(const failure of [()=>{throw Error('access_denied');},()=>({ok:false,error:'access_denied'})]){const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');f.view.queueControls.retained={key:'old',items:[{id:'occurrence'}]};f.host.liveTransport.music=async()=>failure();await f.view.refresh();assert.equal(f.view.playback,null);assert.equal(f.view.queueControls.retained,null);assert.equal(f.view.readState,'error');}finally{f.restore();}}});
test('real player DOM retains same-bound image and queue nodes through disconnect and network read failure',async()=>{const f=domSurface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist'],uri:'spotify:track:0123456789ABCDEFGHIJKL',artwork:{kind:'album_cover',provider:'spotify',url:'https://i.scdn.co/image/cover'}},target:{name:'Actual speaker'}},'first');const key=JSON.stringify(['boot','r0','first',f.view.playback.roomBinding.bindingId,'epoch','device',null,null,null,null,null]);f.view.queueControls.retained={key,items:[{id:'occurrence',title:'Queued song',artist:'Artist',order:1,uri:'spotify:track:0123456789ABCDEFGHIJKL',artwork:null}]};f.view.render();const row=f.nodes.get('queue').children[0],cover=f.nodes.get('cover').src;f.nodes.get('queue').scrollTop=72;f.doc.getElementById('music-detail').hidden=false;f.host.liveTransport.connected=false;f.view.invalidate();assert.equal(f.host.querySelector('.player').hidden,false);assert.equal(f.nodes.get('track-name').textContent,'Actual song');assert.equal(f.nodes.get('player-state').textContent,'Sidst kendt');assert.equal(f.nodes.get('detail-status').textContent,'Sidst kendte afspilning');assert.equal(f.nodes.get('cover').src,cover);assert.equal(f.nodes.get('queue').children[0],row);assert.equal(f.nodes.get('queue').scrollTop,72);assert.equal(f.nodes.get('queue-title').textContent,'Sidst kendte kø');assert.equal(f.nodes.get('music-detail').hidden,false);assert.equal(f.nodes.get('output').disabled,!f.host.liveTransport.connected);assert.equal(f.nodes.get('play-pause').disabled,true);assert.equal(row.disabled,true);row.click();assert.deepEqual(f.selected,[]);f.host.liveTransport.connected=true;f.host.liveTransport.music=async()=>{throw new TypeError('Failed to fetch');};await f.view.refresh();assert.equal(f.nodes.get('track-name').textContent,'Actual song');assert.equal(f.nodes.get('queue').children[0],row);assert.equal(f.nodes.get('output').disabled,false);assert.equal(row.disabled,true);}finally{f.restore();}});
test('foreign room, account, target or owner response clears retained display',async()=>{for(const kind of ['room','account','target','owner']){const f=surface();try{f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');f.view.queueControls.retained={key:'old',items:[{id:'old'}]};if(kind==='room'){f.host.liveSnapshot.roomId='foreign';f.view.lastRead=Date.now();await f.view.refresh();}else{const body=payload('first');if(kind==='account')body.configEntryId='foreign';if(kind==='target')body.data.playback.target.target_id='foreign';if(kind==='owner')body.data.owner_epoch='foreign';f.host.liveTransport.music=async()=>body;await f.view.refresh();}if(kind==='owner'){assert.equal(f.view.playback.owner_epoch,'foreign');assert.equal(f.view.playback.item.name,'Actual song');}else assert.equal(f.view.playback,null,kind);assert.equal(f.view.queueControls.retained,null,kind);}finally{f.restore();}}});
