// Exercise actual controller invalidation/render ownership, not just an invalidate spy.
import {LiveControlView} from '../../podvoice/gatekeeper/static/podview/live-control-view.js';
function ownerControls(f,domain){
 const node=()=>({setAttribute(){},querySelectorAll(){return [];},textContent:''});
 f.host.state={devices:[]};f.host.liveSnapshot.capabilities.controlSetup=['music','vacuum'];
 const controls=Object.create(LiveControlView.prototype);
 Object.assign(controls,{host:f.host,domain,generation:0,opening:0,task:{domain,taskId:'active-'+domain,expiresAt:Date.now()/1000+60},spent:new Map(),receipts:new Map(),body:node(),dialog:{open:true},note:node(),musicButton:{},robotButton:{},renderReceipt(){},renderMusicControls(){},prepareMusic(){}});
 f.host.liveControls=controls;f.host.playerView={renderPlayer(){},renderControls(){},renderQueue(){}};
 f.view.render=LiveMediaView.prototype.render;
 return controls;
}
for(const reason of ['unavailable','expired','binding-change'])for(const domain of ['vacuum','music'])test(`media ${reason} fences music only and preserves ${domain} owner boundary`,async()=>{
 const f=surface();try{
  f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');
  const controls=ownerControls(f,domain);controls.render();const original=controls.task,generation=controls.generation,opening=controls.opening;
  if(reason==='expired'){f.view.playback.expiresAt=Date.now()-1;f.view.render();}
  else if(reason==='binding-change'){f.host.liveSnapshot.mediaRoomBindings=[];f.view.render();}
  else{f.host.liveTransport.music=async()=>({ok:true,schema:'podview.room-playback.v1',bootId:'boot',roomId:'r0',configEntryId:'first',binding:f.host.liveSnapshot.mediaRoomBindings[0],status:'unavailable',data:null});await f.view.refresh();}
  if(domain==='vacuum'){assert.equal(controls.task,original);assert.equal(controls.generation,generation);assert.equal(controls.opening,opening);}else assert.equal(controls.task,null);
  // The connection owner still uses the full invalidation path for either domain.
  f.host.liveTransport.connected=false;controls.invalidate(undefined,false);assert.equal(controls.task,null);assert.ok(controls.generation>generation);
 }finally{f.restore();}
});

