import {controlTask} from '../../podvoice/gatekeeper/static/podview/control-model.js';
test('fresh current observed playback owns its label while original UNKNOWN remains a receipt and independent transport stays enabled',()=>{for(const state of ['playing','paused']){const f=domSurface();try{f.view.account='first';f.view.readState='ready';const now=Date.now(),uri='spotify:track:0123456789ABCDEFGHIJKL',feedback={message:'Udfaldet er ukendt · handlingen gentages ikke.',outcome:'unknown',pending:false,awaitingObservation:false,accountId:'first',targetId:'device',uri:'spotify:playlist:0123456789ABCDEFGHIJKL',requestedAt:now-1000};f.host.liveSelection={feedback,collectionEntry:{actionDispatched:true,selectionSpent:true}};f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:2,observedAt:new Date(now).toISOString(),expiresAt:now+10000,state,item:{uri,name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');f.host.liveSnapshot.capabilities.controlSetup=['music'];f.host.state={devices:[]};f.host.setAttribute=()=>{};const receipts=[];f.host.showFeedback=(message,pending)=>receipts.push({message,pending});const controls=Object.create(LiveControlView.prototype);Object.assign(controls,{host:f.host,spent:new Map(),musicStatus:new DOMNode(),musicDetailStatus:new DOMNode(),musicButton:{},musicFence:null});f.host.liveControls=controls;controls.render=()=>controls.renderMusicControls();const context=controls.musicContext(),task=controlTask({ok:true,schema:'podview.control.v1',bootId:'boot',roomId:'r0',domain:'music',expectedBindingId:f.view.playback.roomBinding.bindingId,taskId:'fresh-independent',revision:1,expiresAt:now/1000+20,options:['pause','resume','next','previous'].map(action=>({id:'fresh-'+action,action,label:action,argsSchema:{kind:'none'}})),setup:{volume:null}},f.host.liveSnapshot,'music');controls.musicOffer={context,task};f.view.render();assert.equal(f.nodes.get('play-pause').disabled,false,'independent native controls remain enabled');assert.equal(f.nodes.get('previous').disabled,false);assert.equal(f.nodes.get('next').disabled,false);assert.equal(f.nodes.get('volume').disabled,true,'unsupported volume is still disabled');assert.equal(f.nodes.get('player-state').textContent,state==='playing'?'Spiller på':'');assert.equal(f.host.liveSelection.feedback,feedback);assert.equal(feedback.outcome,'unknown');assert.equal(f.host.liveSelection.collectionEntry.actionDispatched,true);assert.equal(f.host.liveSelection.collectionEntry.selectionSpent,true);assert.deepEqual(receipts,[{message:feedback.message,pending:false}]);f.view.render();assert.equal(receipts.length,1,'no repeated receipt toast from background renders');assert.equal(controls.musicOffer.task,task);}finally{f.restore();}}});

test('old, foreign, pending or unconfirmed observations never replace UNKNOWN result feedback',()=>{for(const kind of ['stale','expired','old-time','wrong-account','wrong-target','different-track','missing-item','not-ready','offline','pending','accepted','rejected']){const f=domSurface();try{f.view.account='first';f.view.readState='ready';const now=Date.now(),uri='spotify:track:0123456789ABCDEFGHIJKL',feedback={message:'Udfaldet er ukendt · handlingen gentages ikke.',outcome:'unknown',pending:false,awaitingObservation:false,accountId:'first',targetId:'device',uri,requestedAt:now-1000};f.host.liveSelection={feedback};f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:2,observedAt:new Date(now).toISOString(),expiresAt:now+10000,state:'playing',item:{uri,name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');if(kind==='stale')f.view.playback.stale=true;if(kind==='expired')f.view.playback.expiresAt=now-1;if(kind==='old-time')f.view.playback.observedAt=new Date(now-2000).toISOString();if(kind==='wrong-account')feedback.accountId='foreign';if(kind==='wrong-target')feedback.targetId='other';if(kind==='different-track')feedback.uri='spotify:track:1111111111111111111111';if(kind==='missing-item')f.view.playback.item=null;if(kind==='not-ready')f.view.readState='error';if(kind==='offline')f.host.liveTransport.connected=false;if(kind==='pending')feedback.pending=true;if(kind==='accepted')feedback.outcome='accepted';if(kind==='rejected')feedback.outcome='rejected';const receipts=[];f.host.showFeedback=message=>receipts.push(message);let vm;const render=f.host.playerView.renderPlayer.bind(f.host.playerView);f.host.playerView.renderPlayer=value=>{vm=value;render(value);};f.view.render();assert.equal(vm.feedback,feedback,kind);assert.equal(f.host.liveSelection.feedback,feedback,kind);assert.deepEqual(receipts,[],kind);}finally{f.restore();}}});

