import {readFileSync} from 'node:fs';
test('same UNKNOWN receipt is not surfaced again after transient stale state and a newer result clears',()=>{const f=domSurface();try{f.view.account='first';f.view.readState='ready';const now=Date.now(),uri='spotify:track:0123456789ABCDEFGHIJKL',feedback={message:'Udfaldet er ukendt · handlingen gentages ikke.',outcome:'unknown',pending:false,accountId:'first',targetId:'device',uri,requestedAt:now-1000};f.host.liveSelection={feedback,collectionEntry:{actionDispatched:true,selectionSpent:true}};f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:2,observedAt:new Date(now).toISOString(),expiresAt:now+10000,state:'playing',item:{uri,name:'Actual song',artists:['Artist']},target:{name:'Actual speaker'}},'first');const widgetSource=readFileSync(new URL('../../podvoice/gatekeeper/static/podview/widget-view.js',import.meta.url),'utf8'),body=widgetSource.match(/ showFeedback\(message,pending,options=\{\}\)\{([^\n]+)\}/)[1],shown=[],actual=new Function('$','NotificationQueue','applyKitComponent','document',`return function(message,pending,options={}){${body}}`)(id=>f.doc.getElementById(id),class extends NotificationQueue{constructor(render){super(render,{setTimer:()=>1,clearTimer:()=>{}});}},()=>{},{createTextNode:()=>new DOMNode('#text')});f.host.showFeedback=function(message,pending){const previous=this.feedbackMessage;actual.call(this,message,pending);if(message&&previous!==this.feedbackMessage)shown.push(message);};f.view.render();f.view.playback.stale=true;f.view.render();f.host.showFeedback('Nyere handling modtaget',true);f.host.showFeedback('',false);f.view.playback.stale=false;f.view.render();assert.equal(shown.filter(message=>message===feedback.message).length,1);assert.equal(f.nodes.get('player-state').textContent,'Spiller på');assert.equal(f.host.liveSelection.feedback,feedback);assert.equal(feedback.outcome,'unknown');assert.equal(f.host.liveSelection.collectionEntry.selectionSpent,true);f.host.liveSelection.feedback=null;f.view.render();assert.equal(f.view.selectionReceiptFeedback,null);const replacement={...feedback,requestedAt:now-500};f.host.liveSelection.feedback=replacement;f.view.render();assert.equal(f.view.selectionReceiptFeedback,replacement);assert.equal(shown.filter(message=>message===feedback.message).length,2,'new actual receipt may be surfaced once');}finally{f.restore();}});


test('UNKNOWN for a chosen destination cannot be relabeled by current old-room playback on the same Spotify engine',()=>{const f=domSurface();try{f.view.account='first';f.view.readState='ready';const now=Date.now(),uri='spotify:track:0123456789ABCDEFGHIJKL',feedback={message:'Unknown chosen room',outcome:'unknown',pending:false,accountId:'first',targetId:'device',destination:{speakerId:'d'.repeat(64),name:'Frida'},uri,requestedAt:now-1000};let confirmed=false;f.host.liveOutputs={configuredLabel:()=>'',observedDestination:id=>confirmed&&id===feedback.destination.speakerId};f.host.liveSelection={feedback};f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:2,observedAt:new Date(now).toISOString(),expiresAt:now+10000,state:'playing',item:{uri,name:'Actual song',artists:['Artist']},target:{name:'Kitchen'}},'first');const receipts=[];f.host.showFeedback=message=>receipts.push(message);f.view.render();assert.equal(f.nodes.get('player-state').textContent,feedback.message);assert.deepEqual(receipts,[]);confirmed=true;f.view.render();assert.equal(f.nodes.get('player-state').textContent,'Spiller på');assert.deepEqual(receipts,[feedback.message]);assert.equal(f.host.liveSelection.feedback,feedback);assert.equal(feedback.outcome,'unknown');}finally{f.restore();}});

test('account CTA requires actual validated choices and current read access, then focuses the canonical list',()=>{const f=surface();try{f.view.readState='account-selection';f.view.accounts.data={items:[{id:'first',label:'First'},{id:'second',label:'Second'}]};let focused=false;f.view.accounts.setAttribute=()=>{};f.view.accounts.focus=()=>{focused=true;};assert.equal(f.view.canChooseAccount,true);assert.equal(f.view.focusAccountChoice(),true);assert.equal(focused,true);assert.equal(f.view.accounts.hidden,false);f.host.liveTransport.connected=false;assert.equal(f.view.canChooseAccount,false);f.host.liveTransport.connected=true;f.host.liveSnapshot.capabilities.musicRead=['playback'];assert.equal(f.view.canChooseAccount,false);f.host.liveSnapshot.capabilities.musicRead=['targets','playback'];f.view.accounts.data.items=[];assert.equal(f.view.canChooseAccount,false);}finally{f.restore();}});

test('accepted play hook bypasses ordinary poll throttle once and coalesces concurrent accepted reads',async()=>{const f=surface();try{f.view.account='first';f.view.lastRead=Date.now();const first=f.view.captureAcceptedPlayRefresh(),second=f.view.captureAcceptedPlayRefresh(),hold=deferred();f.host.liveTransport.music=(...args)=>{f.calls.push(args);return hold.promise;};const a=first(),b=second();assert.equal(a,b);assert.equal(first(),a);assert.deepEqual(f.calls,[['playback','first']]);hold.resolve(payload('first'));await a;assert.equal(f.view.playback.item.name,'Actual song');await f.view.refresh();assert.equal(f.calls.length,1);}finally{f.restore();}});
for(const change of ['account','boot','room','binding','provider','voice','session','task','revision','transport','disconnect','capability'])test(`captured accepted play refresh suppresses changed ${change} scope`,async()=>{const f=surface();try{f.view.account='first';const accepted=f.view.captureAcceptedPlayRefresh();if(change==='account')f.view.account='second';if(change==='boot')f.host.liveSnapshot.bootId='other';if(change==='room')f.host.liveSnapshot.roomId='other';if(change==='binding')f.host.liveSnapshot.mediaRoomBindings=[];if(change==='provider')f.host.liveSnapshot.providerGeneration=2;if(change==='voice')f.host.liveSnapshot.voice={sessionId:'other'};if(change==='session')f.host.liveSnapshot.sessionId='other';if(change==='task')f.host.liveSnapshot.taskId='other';if(change==='revision')f.host.liveSnapshot.inputRevision=2;if(change==='transport')f.host.liveTransport={...f.host.liveTransport};if(change==='disconnect')f.host.liveTransport.connected=false;if(change==='capability')f.host.liveSnapshot.capabilities.musicRead=[];await accepted();assert.deepEqual(f.calls,[]);}finally{f.restore();}});
test('post acceptance read fences an already pending old poll and never lets its late completion overwrite fresh playback',async()=>{const f=surface();try{f.view.account='first';const old=deferred(),fresh=deferred();let reads=0;f.host.liveTransport.music=()=>++reads===1?old.promise:fresh.promise;const poll=f.view.refresh(),accepted=f.view.captureAcceptedPlayRefresh(),reading=accepted();assert.equal(reads,2);const next=payload('first');next.data.playback.item.name='After accepted play';fresh.resolve(next);await reading;assert.equal(f.view.playback.item.name,'After accepted play');old.resolve(payload('first'));await poll;assert.equal(f.view.playback.item.name,'After accepted play');assert.equal(f.view.pending,false);}finally{f.restore();}});
test('capturing a potential accepted hook alone performs no read or effect',()=>{const f=surface();try{f.view.account='first';f.view.captureAcceptedPlayRefresh();assert.deepEqual(f.calls,[]);assert.equal(f.view.pending,false);}finally{f.restore();}});
for(const change of ['account','boot','provider','session','transport'])test(`accepted playback response cannot publish after in-flight ${change} change`,async()=>{const f=surface();try{f.view.account='first';const hold=deferred();f.host.liveTransport.music=()=>hold.promise;const reading=f.view.captureAcceptedPlayRefresh()();if(change==='account')f.view.account='other';if(change==='boot')f.host.liveSnapshot.bootId='other';if(change==='provider')f.host.liveSnapshot.providerGeneration=2;if(change==='session')f.host.liveSnapshot.sessionId='other';if(change==='transport')f.host.liveTransport={...f.host.liveTransport};hold.resolve(payload('first'));await reading;assert.equal(f.view.playback,undefined);}finally{f.restore();}});

test('a pending explicit choice replaces prior observation presentation and disables old playback controls',()=>{
 const f=domSurface();try{f.view.account='first';f.view.readState='ready';const selected={title:'Chosen song',artist:'Chosen artist',uri:'spotify:track:1111111111111111111111',target:'Kitchen',artwork:{kind:'album_cover',provider:'spotify',url:'https://i.scdn.co/image/chosen'}};f.host.liveSelection={feedback:{message:'Waiting',pending:true},pendingPlayer:()=>selected};f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:2,state:'playing',item:{uri:'spotify:track:0123456789ABCDEFGHIJKL',name:'Old song',artists:['Old artist']},target:{name:'Kitchen'}},'first');let vm,lastControls;f.host.playerView.renderPlayer=value=>vm=value;f.host.playerView.renderControls=value=>lastControls=value;f.view.render();assert.equal(vm.title,'Chosen song');assert.equal(vm.playing,false);assert.equal(vm.active,true);assert.equal(vm.loading,true);assert.equal(vm.progressMs,null);assert.equal(vm.feedback.message,'Starter afspilning…');assert.equal(lastControls.blocked,true);assert.equal(f.view.playback.item.name,'Old song','actual observation remains independent');f.host.liveSelection.pendingPlayer=()=>null;f.host.liveSelection.feedback={message:'Unknown outcome',pending:false,outcome:'unknown'};f.view.render();assert.equal(vm.title,'Old song');assert.equal(vm.feedback.message,'Unknown outcome');}finally{f.restore();}
});

test('actual rejected queue choice keeps known rows with a choice heading while a later read failure uses the read heading',async()=>{
 const f=domSurface();try{
  f.view.account='first';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state:'playing',item:{name:'Actual song',artists:['Artist'],uri:'spotify:track:0123456789ABCDEFGHIJKL'},target:{name:'Actual speaker'}},'first');f.host.liveSnapshot.capabilities.queueSelection=true;
  const item={id:'a'.repeat(24),title:'Known queued song',artist:'Artist',uri:'spotify:track:'+'0'.repeat(22),artwork:null,order:1},offer={ok:true,schema:'podview.queue-offer.v1',bootId:'boot',roomId:'r0',accountId:'first',targetId:'device',expectedBindingId:f.view.playback.roomBinding.bindingId,taskId:'queue:'+'b'.repeat(32),revision:1,expiresInMs:8000,ownerEpoch:'epoch',pollSequence:1,truncated:false,items:[item]};
  let effects=0;f.host.liveTransport.queueOffer=async()=>offer;f.host.liveTransport.queueAction=async()=>{effects++;return {outcome:'rejected'};};await f.view.loadQueue();const row=f.host.playerView.rows.get(item.id);assert.ok(row);await f.view.queueControls.choose(item);assert.equal(f.view.queueControls.status,'error');assert.equal(f.view.queueControls.model('first',f.view.playback).errorKind,'choice');assert.equal(f.nodes.get('queue-title').textContent,'Køvalget blev afvist');assert.equal(f.host.playerView.rows.get(item.id),row);assert.equal(row.disabled,true);assert.equal(effects,1);f.view.renderQueue();assert.equal(f.nodes.get('queue-title').textContent,'Køvalget blev afvist');
  f.host.liveTransport.queueOffer=async()=>{throw Error('read503');};await f.view.loadQueue();assert.equal(f.view.queueControls.status,'error');assert.equal(f.nodes.get('queue-title').textContent,'Køen kunne ikke hentes');assert.equal(f.host.playerView.rows.get(item.id),row);assert.equal(row.disabled,true);assert.equal(f.view.queueControls.model('first',f.view.playback).errorKind,'read');assert.equal(effects,1);f.view.queueControls.invalidate(true);assert.equal(f.view.queueControls.errorKind,null);
 }finally{f.view.queueControls.invalidate(true);f.restore();}
});

test('persistent next destination is projected only for idle, never over observed playing/paused output or pending start',()=>{
 const f=surface(),shown=[];try{f.view.account='first';f.view.readState='ready';f.host.liveOutputs={configuredLabel:()=> 'Køkkenalrum HomePod',nextDestinationLabel:()=> 'Svend’s HomePod'};f.host.playerView={renderPlayer:vm=>shown.push(vm),renderControls(){},renderQueue(){}};f.view.render=LiveMediaView.prototype.render;f.view.renderQueue=LiveMediaView.prototype.renderQueue;
  f.view.render();assert.equal(shown.at(-1).active,false);assert.equal(shown.at(-1).nextDestinationLabel,'Svend’s HomePod');assert.equal(shown.at(-1).configuredTarget,'Køkkenalrum HomePod');assert.equal(shown.at(-1).target,'');
  for(const state of ['playing','paused']){f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,expiresAt:Date.now()+10000,state,item:{name:'Actual song',artists:['Artist']},target:{name:'Observed kitchen speaker'}},'first');f.view.render();assert.equal(shown.at(-1).active,true);assert.equal(shown.at(-1).target,'Observed kitchen speaker');assert.equal(shown.at(-1).nextDestinationLabel,'');}
  f.view.playback=null;f.host.liveSelection={pendingPlayer:()=>({title:'Chosen source',target:'Svend’s HomePod'}),pending:true};f.view.render();assert.equal(shown.at(-1).active,true);assert.equal(shown.at(-1).loading,true);assert.equal(shown.at(-1).nextDestinationLabel,'');assert.deepEqual(f.calls,[]);
 }finally{f.restore();}
});

test('actual player DOM shows account-observed paused track plus explicit paused/unconfirmed wording and no queue or controls',async()=>{
 const {roomPlaybackObservation}=await import('../../podvoice/gatekeeper/static/podview/media-observation.js'),f=domSurface();try{f.host.live=true;f.view.account='first';f.view.readState='ready';const wire=payload('first');wire.status='account_observed';delete wire.data.room_proof_valid_until;wire.data.playback={...wire.data.playback,state:'paused',progress_ms:null,provider_changed_at_ms:null,shuffle:null,repeat:null};f.view.playback=roomPlaybackObservation(wire,'first',f.host.liveSnapshot);f.view.render();assert.equal(f.nodes.get('track-name').textContent,'Actual song');assert.equal(f.nodes.get('track-artist').textContent,'Artist');assert.equal(f.nodes.get('player-state').textContent,'På pause · højttaler ikke bekræftet');assert.equal(f.nodes.get('detail-status').textContent,'Kontostatus · på pause · højttaler ikke bekræftet');assert.match(f.nodes.get('output').getAttribute('aria-label'),/Kontostatus · Vælg næste højttaler/);assert.equal(f.nodes.get('output').getAttribute('aria-label').includes('Aktuelt output'),false);for(const id of ['previous','next','play-pause','detail-previous','detail-next','detail-toggle','volume','detail-volume'])assert.equal(f.nodes.get(id).disabled,true,id);assert.equal(f.host.playerView.progressVM.canSeek,false);assert.equal(f.host.playerView.rows.size,0);assert.deepEqual(f.calls,[]);
 }finally{f.restore();}
});

const v2Payload=()=>{const w=payload('first');w.schema='podview.room-playback.v2';w.reason=null;w.binding={...w.binding,targetId:'external',nativeRoomId:'actual-room',nativeHomepodId:'actual-speaker',bindingId:'a'.repeat(64),validUntil:Date.now()/1000+10};delete w.data.room_proof_valid_until;w.data.playback={...w.data.playback,target:{kind:'spotify_device',target_id:'external',name:'Spotify bridge'},progress_ms:100,provider_changed_at_ms:null,shuffle:false,repeat:'off'};return w;};
test('v2 actual external output stays independent of configured destination and changes revoke old command context',async()=>{
 const f=surface();try{f.view.account='first';f.host.liveOutputs={refreshConfiguredLabel(){},actualLabel:b=>b?.nativeHomepodId==='actual-speaker'?'Kitchen':'Office'};let body=v2Payload(),invalidations=0;f.host.liveControls={invalidateMusic(){invalidations++;}};f.host.liveTransport.music=async()=>body;await f.view.refresh({immediate:true});assert.equal(f.view.playback.target.id,'external');assert.equal(f.view.playback.actualTargetLabel,'Kitchen');const first=f.view.playback;f.host.liveSnapshot.mediaRoomBindings=[];await f.view.refresh({immediate:true});assert.equal(f.view.playback.target.id,'external');assert.equal(f.view.playback.roomBinding.bindingId,first.roomBinding.bindingId);const before=invalidations;body=v2Payload();body.binding={...body.binding,bindingId:'c'.repeat(64),nativeHomepodId:'other'};body.data.playback.state='paused';await f.view.refresh({immediate:true});assert.equal(f.view.playback.state,'paused');assert.equal(f.view.playback.actualTargetLabel,'Office');assert.ok(invalidations>before);
 }finally{f.restore();}
});
test('v2 unavailable retains only same-scope read-only history; idle clears history; owner change clears old history',async()=>{
 for(const terminal of ['idle','owner_changed']){const f=surface();try{f.view.account='first';let body=v2Payload();f.host.liveTransport.music=async()=>body;await f.view.refresh({immediate:true});body={...body,status:'unavailable',reason:'stale_observation',binding:null,data:null};await f.view.refresh({immediate:true});assert.equal(f.view.playback.item.name,'Actual song');assert.equal(f.view.playback.stale,true);assert.equal(f.view.playback.displayRetained,true);assert.equal(f.view.readState,'unavailable');assert.equal(f.view.account,'first');if(terminal==='idle'){body=v2Payload();body.status='idle';body.binding=null;body.data.playback={state:'no_active_playback',item:null,target:null};}else body.reason='owner_changed';await f.view.refresh({immediate:true});assert.equal(f.view.playback,null);assert.equal(f.view.account,'first');assert.equal(f.view.readState,terminal==='idle'?'idle':'unavailable');}finally{f.restore();}}
});
test('v2 metadata-only playback survives transient read loss and recovers fresh without a default binding',async()=>{
 const f=surface();try{f.view.account='first';f.host.liveSnapshot.mediaRoomBindings=[];const body=v2Payload();body.status='account_observed';body.reason='route_unavailable';body.binding=null;f.host.liveTransport.music=async()=>body;await f.view.refresh({immediate:true});assert.equal(f.view.playback.accountObserved,true);assert.equal(f.view.playback.actualTargetLabel,undefined);f.host.liveTransport.music=async()=>{throw new TypeError('network');};await f.view.refresh({immediate:true});assert.equal(f.view.playback.displayRetained,true);assert.equal(f.view.playback.stale,true);f.host.liveTransport.music=async()=>body;await f.view.refresh({immediate:true});assert.equal(f.view.playback.stale,undefined);assert.equal(f.view.readState,'ready');assert.equal(f.view.playback.accountObserved,true);}finally{f.restore();}
});

function nativeVolumeSurface(){const f=domSurface(),now=Date.now();f.host.live=true;f.host.state={devices:[]};f.host.setAttribute=()=>{};f.view.account='first';f.view.readState='ready';f.view.playback=boundPlayback(f.host.liveSnapshot,{owner_epoch:'epoch',poll_sequence:1,observedAt:new Date(now).toISOString(),expiresAt:now+15000,state:'playing',item:{uri:'spotify:track:0123456789ABCDEFGHIJKL',name:'Actual song',artists:['Artist'],duration_ms:180000},target:{name:'Actual speaker'}},'first');f.host.liveSnapshot.capabilities.controlSetup=['music'];const controls=Object.create(LiveControlView.prototype);Object.assign(controls,{host:f.host,spent:new Map(),receipts:new Map(),musicStatus:new DOMNode(),musicDetailStatus:new DOMNode(),musicButton:{},robotButton:{},dialog:{open:false},body:{setAttribute(){},querySelectorAll(){return [];}},generation:0,opening:0,renderReceipt(){},prepareMusic(){}});f.host.liveControls=controls;const context=controls.musicContext(),task=controlTask({ok:true,schema:'podview.control.v1',bootId:'boot',roomId:'r0',domain:'music',expectedBindingId:f.view.playback.roomBinding.bindingId,taskId:'current-volume',revision:1,expiresAt:now/1000+20,options:[{id:'volume-current',action:'volume',label:'Lydstyrke',argsSchema:{kind:'percent',min:0,max:60}}],setup:{volume:35}},f.host.liveSnapshot,'music');controls.musicOffer={context,task};f.view.render();return {...f,controls};}

test('actual repeated media renders preserve known35 slider without intermediate disabled or zero writes',()=>{
 const f=nativeVolumeSurface(),writes=[];try{for(const id of ['volume','detail-volume']){const node=f.nodes.get(id);assert.equal(node.disabled,false);assert.equal(node.value,'35');for(const key of ['disabled','value']){let value=node[key];Object.defineProperty(node,key,{configurable:true,get:()=>value,set:next=>{writes.push({id,key,value:next});value=next;}});}}
  for(let revision=2;revision<=4;revision++){f.host.liveSnapshot={...f.host.liveSnapshot,revision};f.view.render();}
  assert.deepEqual(writes,[]);for(const id of ['volume','detail-volume']){assert.equal(f.nodes.get(id).disabled,false);assert.equal(f.nodes.get(id).value,'35');}assert.deepEqual(f.calls,[]);
 }finally{f.restore();}
});

for(const change of ['capability','offline','selected-pending'])test(`canonical control owner still blocks volume on actual ${change}`,()=>{
 const f=nativeVolumeSurface();try{if(change==='capability')f.host.liveSnapshot.capabilities.controlSetup=[];if(change==='offline')f.host.liveTransport.connected=false;if(change==='selected-pending')f.host.liveSelection={pending:true,pendingPlayer:()=>({title:'Chosen song',artist:'Chosen artist',target:'Actual speaker'})};f.view.render();for(const id of ['volume','detail-volume'])assert.equal(f.nodes.get(id).disabled,true,id);assert.deepEqual(f.calls,[]);}finally{f.restore();}
});

for(const [metadataMs,routeMs]of [[15000,5000],[5000,15000]])test(`actual v2 read cadence respects earlier source deadline metadata${metadataMs} route${routeMs}`,async()=>{
 const previousNow=Date.now;let clock=previousNow();Date.now=()=>clock;const f=surface();try{f.view.account='first';let reads=0;f.host.liveTransport.music=async()=>{reads++;const body=v2Payload();body.binding.validUntil=(clock+routeMs)/1000;body.data.observation={...body.data.observation,observed_at:new Date(clock).toISOString(),age_ms:0,max_age_ms:metadataMs};return body;};await f.view.refresh({immediate:true});assert.equal(f.view.playback.expiresAt,clock+metadataMs);assert.equal(f.view.playback.roomBinding.validUntil,(clock+routeMs)/1000);assert.ok(f.view.refreshInterval<=2500);assert.ok(f.view.refreshInterval>=2400);clock+=2000;await f.view.refresh();assert.equal(reads,1);clock+=600;await f.view.refresh();assert.equal(reads,2);assert.equal(f.view.pending,false);}finally{f.restore();Date.now=previousNow;}
});

test('v2 unavailable source keeps bounded8000 cadence instead of spinning on absent route deadline',async()=>{
 const f=surface();try{f.view.account='first';let reads=0;f.host.liveTransport.music=async()=>{reads++;return {...v2Payload(),status:'unavailable',reason:'account_unavailable',binding:null,data:null};};await f.view.refresh({immediate:true});assert.equal(f.view.refreshInterval,8000);await f.view.refresh();assert.equal(reads,1);assert.equal(f.view.pending,false);}finally{f.restore();}
});
